Object.assign(Z_STRINGS.en, {"faq.titleA": "FAQ", "faq.titleB": "Troubleshooting", "faq.subtitle": "Fast answers to common problems.", "faq.loginAccess": "Login & access", "faq.lanA": "LAN / tunnel mode (", "faq.lanB": ") serves the panel over plain HTTP. Anyone on that network can sniff your session — only use it on networks you trust, or reach the panel through an encrypted SSH tunnel instead.", "faq.tooMany": "“Too many attempts, try again in a few minutes”", "faq.tooManyT": "You (or someone) failed login 8+ times in 15 minutes. Wait, then log in carefully. If it persists with the right password, restart the panel service — in-memory counters reset:", "faq.pwLost": "Password lost", "faq.pwLostA": "SSH into the server and set a new one via environment + restart, or edit", "faq.pwLostB": "in", "faq.pwLostC": "— note this only applies to a", "faq.pwLostFresh": "fresh", "faq.pwLostD": "database. On an existing DB, stop the service, delete", "faq.pwLostE": "(you lose data — restore from backup after), and restart to trigger first-run creation.", "faq.api403": "API returns 403 “forbidden” on POST", "faq.api403A": "You forgot the", "faq.api403B": "header — the CSRF guard. Browsers using the panel send it automatically.", "faq.panelDown": "Panel not responding", "faq.portTaken": "If the port is taken, another copy is already running — stop it before starting a new one.", "faq.subs404": "Subscriptions show 404 for everyone", "faq.subs404A": "Tokens rotate on", "faq.resetToken": "Reset token", "faq.subs404B": "— resend the new link.", "faq.subs404C": "Check the user is active, not expired and not out of volume.", "faq.subs404D": "If you renamed", "faq.subs404E": ", old", "faq.subs404F": "links stop working.", "faq.sslFails": "SSL fails", "faq.sslA": "Port 80 must be free and the domain's DNS must point at the server.", "faq.sslB": "Let's Encrypt rate-limits repeated issuance — wait an hour and retry.", "faq.sslC": "Behind Nginx, make sure the HTTP vhost exists before issuing.", "faq.clientsTitle": "Clients can't connect but the sub link loads", "faq.clientsA": "Open the VPN ports on the firewall (", "faq.clientsB": ", plus inbound / Hy2 / WG ports).", "faq.settingsServer": "Settings → Server", "faq.clientsD": "domain/ports match reality, and the REALITY public key is generated.", "faq.clientsE": "WireGuard shows a warning comment until you paste the server's public key in Settings.", "faq.payTitle": "Do I have to pay for any of this?", "faq.payText": "No. Zefira is MIT-licensed, the docs site is plain static files in this repo, and GitHub Pages hosting is free. Let's Encrypt certificates are free too."});
Object.assign(Z_STRINGS.fa, {"faq.titleA": "سؤالات پرتکرار", "faq.titleB": "عیب‌یابی", "faq.subtitle": "جواب‌های سریع برای مشکلات رایج.", "faq.loginAccess": "ورود و دسترسی", "faq.lanA": "حالت LAN / تانل (", "faq.lanB": ") پنل را روی HTTP ساده سرو می‌کند. هرکس در آن شبکه باشد می‌تواند نشستت را شنود کند — فقط در شبکه‌های مورداعتماد، یا از تونل SSH رمزنگاری‌شده وصل شو.", "faq.tooMany": "«تلاش‌های زیاد، چند دقیقه دیگر امتحان کن»", "faq.tooManyT": "تو (یا کسی) ۸+ بار در ۱۵ دقیقه لاگین ناموفق داشتی. صبر کن بعد با دقت وارد شو. اگر با پسورد درست ادامه داشت، سرویس پنل را ری‌استارت کن — شمارنده‌های حافظه‌ای ریست می‌شوند:", "faq.pwLost": "پسورد گم شد", "faq.pwLostA": "با SSH به سرور برو و با environment + ری‌استارت یکی تازه بگذار، یا ویرایش کن", "faq.pwLostB": "در", "faq.pwLostC": "— دقت: این فقط برای دیتابیس", "faq.pwLostFresh": "تازه", "faq.pwLostD": "صدق می‌کند. روی دیتابیس موجود، سرویس را stop کن، حذف کن", "faq.pwLostE": "(دیتا می‌پرد — بعد از بکاپ برگردان)، و ری‌استارت کن تا ساخت first-run فعال شود.", "faq.api403": "API روی POST خطای 403 می‌دهد", "faq.api403A": "یادت رفت", "faq.api403B": "هدر — گارد CSRF. مرورگرهایی که پنل را استفاده می‌کنند خودکار می‌فرستند.", "faq.panelDown": "پنل جواب نمی‌دهد", "faq.portTaken": "اگر پورت گرفته شده، یک نسخه دیگر در حال اجراست — قبل از اجرای جدید stopش کن.", "faq.subs404": "اشتراک همه 404 می‌دهد", "faq.subs404A": "توکن‌ها با", "faq.resetToken": "ریست توکن", "faq.subs404B": "— لینک جدید را بفرست.", "faq.subs404C": "چک کن کاربر فعال باشد، منقضی نشده و حجمش تمام نشده باشد.", "faq.subs404D": "اگر عوض کردی", "faq.subs404E": "، قدیمی", "faq.subs404F": "لینک‌ها کار نمی‌کنند.", "faq.sslFails": "SSL خراب است", "faq.sslA": "پورت ۸۰ باید آزاد باشد و DNS دامنه به سرور اشاره کند.", "faq.sslB": "Let's Encrypt صدور تکراری را محدود می‌کند — یک ساعت صبر کن و دوباره بزن.", "faq.sslC": "پشت Nginx مطمئن شو vhost مدل HTTP قبل از صدور هست.", "faq.clientsTitle": "کلاینت‌ها وصل نمی‌شوند ولی لینک ساب لود می‌شود", "faq.clientsA": "پورت‌های VPN را روی فایروال باز کن (", "faq.clientsB": "، به‌علاوه پورت‌های inbound / Hy2 / WG).", "faq.settingsServer": "تنظیمات → سرور", "faq.clientsD": "دامنه/پورت‌ها با واقعیت بخوانند و کلید عمومی REALITY ساخته شده باشد.", "faq.clientsE": "WireGuard تا وقتی کلید عمومی سرور را در تنظیمات نچسبانی کامنت هشدار نشان می‌دهد.", "faq.payTitle": "باید برای چیزی پول بدهم؟", "faq.payText": "نه. زفیرا MIT است، سایت داکس فایل‌های استاتیک همین ریپوست و هاست GitHub Pages رایگان است. گواهی‌های Let's Encrypt هم رایگان‌اند."});
Object.assign(Z_STRINGS.zh, {"faq.titleA": "常见问题", "faq.titleB": "排错", "faq.subtitle": "常见问题的快速答案。", "faq.loginAccess": "登录与访问", "faq.lanA": "局域网 / 隧道模式 (", "faq.lanB": ") 面板走明文 HTTP。同一网络的人能嗅探你的会话 — 只在信任的网络使用,或走加密 SSH 隧道。", "faq.tooMany": "“尝试过多,请几分钟后再试”", "faq.tooManyT": "你 (或他人) 15 分钟内登录失败 8+ 次。等一等再认真登录。如果密码正确还不行,重启面板服务 — 内存计数器会重置:", "faq.pwLost": "忘记密码", "faq.pwLostA": "SSH 上服务器,用环境变量 + 重启设个新的,或编辑", "faq.pwLostB": "在", "faq.pwLostC": "— 注意这只适用于", "faq.pwLostFresh": "全新", "faq.pwLostD": "数据库。在已有数据库上,停掉服务,删除", "faq.pwLostE": "(数据会丢 — 之后从备份恢复),然后重启以触发首次运行创建。", "faq.api403": "API POST 返回 403", "faq.api403A": "你忘了加", "faq.api403B": "请求头 — CSRF 防护。用面板的浏览器会自动发送。", "faq.panelDown": "面板无响应", "faq.portTaken": "如果端口被占,说明已有实例在跑 — 先停掉再开新的。", "faq.subs404": "所有订阅都 404", "faq.subs404A": "令牌会通过下述操作轮换", "faq.resetToken": "重置令牌", "faq.subs404B": "— 请重发新链接。", "faq.subs404C": "检查用户是否正常、未过期、流量未用完。", "faq.subs404D": "如果你改了", "faq.subs404E": ",旧的", "faq.subs404F": "链接会失效。", "faq.sslFails": "SSL 失败", "faq.sslA": "80 端口必须空闲,域名 DNS 必须指向本机。", "faq.sslB": "Let's Encrypt 限流重复签发 — 等一小时再试。", "faq.sslC": "Nginx 后面,先确认 HTTP vhost 存在再签发。", "faq.clientsTitle": "客户端连不上但订阅能加载", "faq.clientsA": "在防火墙上放行 VPN 端口 (", "faq.clientsB": ",以及 inbound / Hy2 / WG 端口)。", "faq.settingsServer": "设置 → 服务器", "faq.clientsD": "域名/端口与实际一致,且已生成 REALITY 公钥。", "faq.clientsE": "在设置里粘贴服务器公钥之前,WireGuard 会显示警告注释。", "faq.payTitle": "这些要收费吗？", "faq.payText": "不用。Zefira 是 MIT 许可,文档站就是本仓库的静态文件,GitHub Pages 托管免费。Let's Encrypt 证书也免费。"});
Object.assign(Z_STRINGS.ru, {"faq.titleA": "FAQ", "faq.titleB": "Отладка", "faq.subtitle": "Быстрые ответы на частые проблемы.", "faq.loginAccess": "Вход и доступ", "faq.lanA": "Режим LAN / туннеля (", "faq.lanB": ") панель отдаётся по plain HTTP. Любой в этой сети может сниффить сессию — только доверенные сети или SSH-туннель.", "faq.tooMany": "«Слишком много попыток, попробуй через пару минут»", "faq.tooManyT": "Ты (или кто-то) 8+ раз за 15 минут провалил вход. Подожди и зайди аккуратно. Если с верным паролем повторяется — рестартни сервис панели, счётчики в памяти сбросятся:", "faq.pwLost": "Потерян пароль", "faq.pwLostA": "Зайди по SSH и задай новый через environment + рестарт, или отредактируй", "faq.pwLostB": "в", "faq.pwLostC": "— учти, это только для", "faq.pwLostFresh": "свежей", "faq.pwLostD": "базы. На существующей БД останови сервис, удали", "faq.pwLostE": "(данные потеряются — восстанови из бэкапа после), и рестартни для first-run создания.", "faq.api403": "API отвечает 403 на POST", "faq.api403A": "Ты забыл", "faq.api403B": "хедер — CSRF-защита. Браузеры с панелью шлют его сами.", "faq.panelDown": "Панель не отвечает", "faq.portTaken": "Если порт занят — уже крутится другая копия, останови её сначала.", "faq.subs404": "Подписки 404 у всех", "faq.subs404A": "Токены ротируются через", "faq.resetToken": "Сброс токена", "faq.subs404B": "— разошли новую ссылку.", "faq.subs404C": "Проверь: юзер активен, не истёк и не без трафика.", "faq.subs404D": "Если переименовал", "faq.subs404E": ", старые", "faq.subs404F": "ссылки умрут.", "faq.sslFails": "SSL падает", "faq.sslA": "Порт 80 свободен и DNS домена смотрит на сервер.", "faq.sslB": "Let's Encrypt режет частые выпуски — подожди час.", "faq.sslC": "За Nginx убедись, что HTTP-vhost существует.", "faq.clientsTitle": "Клиенты не коннектятся, а саб грузится", "faq.clientsA": "Открой VPN-порты на фаерволе (", "faq.clientsB": ", плюс порты inbound / Hy2 / WG).", "faq.settingsServer": "Настройки → Сервер", "faq.clientsD": "домен/порты совпадают и публичный ключ REALITY создан.", "faq.clientsE": "WireGuard показывает варнинг, пока не вставишь публичный ключ сервера в настройках.", "faq.payTitle": "Это всё платное?", "faq.payText": "Нет. Zefira под MIT, сайт доков — статика этого репо, хостинг GitHub Pages бесплатен. Сертификаты Let's Encrypt тоже бесплатны."});

